#include <set>
#include <multiset>
#include <iostream>

int main() {
    std::set<int> s = {10, 20, 30};
    std::multiset<int> ms = {5, 5, 15, 25};

    // Set: returns 0 or 1
    size_t count1 = s.erase(20); 
    size_t count2 = s.erase(99); 
    std::cout << "Set erased 20: " << count1 << " (Expected 1)\n";

    // Multiset: returns total count of duplicates removed
    size_t count3 = ms.erase(5);
    std::cout << "Multiset erased 5: " << count3 << " (Expected 2)\n";
}
